public class ThreeTokenCalculatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + quote(expected) + " but got " + quote(actual));
            failures++;
        }
    }

    static String quote(Object value) {
        if (value == null) {
            return "null";
        }
        return "\"" + value.toString().replace("\n", "\\n") + "\"";
    }

    static String run(String... args) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            ThreeTokenCalculator.main(args);
        } catch (RuntimeException ex) {
            System.setOut(old);
            return "threw " + ex;
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        String usage = "usage: java ThreeTokenCalculator <number> <operator> <number>\n";
        check("3 + 4", "3 + 4 = 7\n", run("3", "+", "4"));
        check("10 - 25", "10 - 25 = -15\n", run("10", "-", "25"));
        check("6 * 7", "6 * 7 = 42\n", run("6", "*", "7"));
        check("10 / 3 -- integer division", "10 / 3 = 3\n", run("10", "/", "3"));
        check("5 / 0", "error: cannot divide by zero\n", run("5", "/", "0"));
        check("unknown operator", "error: unknown operator ^\n", run("2", "^", "8"));
        check("too few arguments", usage, run("3", "+"));
        check("no arguments", usage, run());
        check("too many arguments", usage, run("3", "+", "4", "5"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

