public class ThreeTokenCalculator {

    public static void main(String[] args) {
        if (args.length != 3) {
            System.out.println("usage: java ThreeTokenCalculator <number> <operator> <number>");
            return;
        }
        int left = Integer.parseInt(args[0]);
        String operator = args[1];
        int right = Integer.parseInt(args[2]);

        int result;
        switch (operator) {
            case "+":
                result = left + right;
                break;
            case "-":
                result = left - right;
                break;
            case "*":
                result = left * right;
                break;
            case "/":
                if (right == 0) {
                    System.out.println("error: cannot divide by zero");
                    return;
                }
                result = left / right;
                break;
            default:
                System.out.println("error: unknown operator " + operator);
                return;
        }
        System.out.println(left + " " + operator + " " + right + " = " + result);
    }
}
